import React, { useState, useEffect } from "react"

const SearchResults = ({results}) => {
    return (
        <div className="results-list"> 
        {results.map((result, id) => {
            return <div key={id}>{result.firstname} {result.lastname} </div>
        })}
        </div>
    )
}

export default SearchResults
